use std::{fs, path::Path};

use regex::regex;

use crate::{
    common::{
        argument::{Argument, ArgumentList},
        constraint::Constraint,
        intrinsic::Intrinsic,
        intrinsic_helpers::{IntrinsicType, Sign, TypeKind},
    },
    riscv::{Riscv, intrinsic::RiscvIntrinsicType},
};

// Parse the .spec files generated by stdarch-gen-riscv
pub fn get_intrinsics(
    filename: &Path,
) -> Result<Vec<Intrinsic<Riscv>>, Box<dyn std::error::Error>> {
    let mut intrinsics = vec![];
    let contents = fs::read_to_string(filename)?;
    let mut lines = contents.lines();
    while let Some(mut line) = lines.next() {
        let Some(name) = line.strip_prefix("name = ") else {
            continue;
        };

        line = lines.next().unwrap();
        let arch = line.trim_prefix("arch = ");
        let arch_tags = if arch == "rv32" {
            vec!["rv32".to_string()]
        } else if arch == "rv64" {
            vec!["rv64".to_string()]
        } else {
            vec![]
        };

        line = lines.next().unwrap();
        let return_type = line.trim_prefix("return_type = ");
        let results = parse_spec_type(return_type);

        line = lines.next().unwrap();
        let arguments = line.trim_prefix("arguments = ");
        let arguments = ArgumentList {
            args: arguments
                .split(", ")
                .enumerate()
                .map(|(idx, arg)| parse_argument(arg, idx))
                .collect(),
        };

        line = lines.next().unwrap();
        let extensions = line
            .trim_prefix("extensions = ")
            .split(", ")
            .map(ToString::to_string)
            .collect();

        intrinsics.push(Intrinsic {
            name: name.to_string(),
            arguments,
            results,
            arch_tags,
            extensions,
        });
    }
    Ok(intrinsics)
}

fn parse_spec_type(input: &str) -> RiscvIntrinsicType {
    let (input, constant) = match input.strip_prefix("const ") {
        Some(input) => (input, true),
        None => (input, false),
    };

    let (kind, bit_len) = match input {
        "uint32_t" => (TypeKind::Int(Sign::Unsigned), 32),
        "uint64_t" => (TypeKind::Int(Sign::Unsigned), 64),
        "int" => (TypeKind::Int(Sign::Signed), 32),
        "unsigned" => (TypeKind::Int(Sign::Unsigned), 32),
        c_type => panic!("unsupported RISC-V type {c_type}"),
    };

    RiscvIntrinsicType(IntrinsicType {
        constant,
        ptr_constant: false,
        ptr: false,
        kind,
        bit_len: Some(bit_len),
        simd_len: None,
        vec_len: None,
    })
}

fn parse_argument(input: &str, pos: usize) -> Argument<Riscv> {
    let captures = regex!(r"^(.*?)(\w+)\s*$").captures(input).unwrap();
    let c_type = captures[1].trim();
    let ty = parse_spec_type(c_type);
    let name = captures[2].trim().to_string();
    let constraint = ty.constant.then(|| constant_constraint(&name));
    Argument {
        pos,
        name,
        ty,
        constraint,
        is_predicate: false,
    }
}

// The header files don't include information about the constraints on constant parameters,
// so we have to hard-code them instead
fn constant_constraint(name: &str) -> Constraint {
    match name {
        "bs" => Constraint::Range(0..4),
        "rnum" => Constraint::Range(0..11),
        name => panic!("unrecognized constant {name}"),
    }
}
